    private static void production()throws Exception{
        Pc1RenderContextTests.Font font=new Pc1RenderContextTests.Font();Pc1RenderContextTests.Fixture f=new Pc1RenderContextTests.Fixture(font,null);
        Pc1GraphicsPipeline.Services leaves=(Pc1GraphicsPipeline.Services)Proxy.newProxyInstance(Pc1GraphicsPipeline.Services.class.getClassLoader(),new Class<?>[]{Pc1GraphicsPipeline.Services.class},(p,m,a)->{throw new IOException("unexpected fixture graphics leaf "+m.getName());});Pc1GraphicsPipeline graph=new Pc1GraphicsPipeline(f.host.pc1,new Pc1Compositor(Pc1RenderContextTests.solid(64,48,0x123456)),Pc1GlyphCache.zeroBss(),font,f.backend,leaves);f.context=graph.render();f.initializeKnownScene();boolean[] blocked={false};
        Pc1Audio.Backend device=(Pc1Audio.Backend)Proxy.newProxyInstance(Pc1Audio.Backend.class.getClassLoader(),new Class<?>[]{Pc1Audio.Backend.class},(p,m,a)->{if(m.getName().equals("pcmInitialized"))return false;if(m.getName().equals("bindControl"))return null;throw new IOException("unexpected physical audio "+m.getName());});Pc1Audio audio=new Pc1Audio(device,f.host.pc1.catalogMemory().audioCatalog());Pc1Timer5 timer=new Pc1Timer5(f.host.pc1,graph,audio,()->{try{f.host.save(new DataOutputStream(new ByteArrayOutputStream()));}catch(IOException expected){blocked[0]=true;}return f.host.nativeSettings();});
        f.memory.writeInt(0x9da4b4,0);f.memory.writeInt(0x9d8a20,11);f.memory.writeInt(0x9da4c0,0);f.host.pc1.codeBuffer().writeBytes(0,bytes(CODE));for(int n=0;n<5;n++)f.host.pc1.nativeMemory().writeAddress(Pc1Timer5.CALLBACK+n,new byte[]{'C','A','L','L',0}[n]);int expected=new Pc1LabelScanner(f.host.pc1.nativeMemory()).find(Pc1Timer5.CALLBACK);
        byte[] pixels=graph.render().compositor().front().bgr24();check(timer.tick()==1&&f.memory.readInt(0x9d8a20)==-1&&f.memory.readInt(0x9d8a14)==expected,"complete timer uses same raw label scanner, PC and wait owner");check(blocked[0],"whole Host snapshot blocked through settings/audio callback");for(int at:new int[]{Pc1Timer5.CALLBACK,0x9d95dc,0x9d95fc})for(int n=0;n<32;n++)check(f.host.pc1.nativeMemory().readAddress(at+n)==0,"all three native32-byte callback cells clear");check(Arrays.equals(pixels,graph.render().compositor().front().bgr24()),"disabled effects/head leave persistent pixels intact without a repaint substitution");
    }
    public static int run()throws Exception{
        checks=0;check(TIMERS.length==227&&LABELS.length==60,"all actual timer/scanner programs present");
        for(String row:TIMERS){String[] v=row.split("\\|");Fixture f=new Fixture(ints(v[0]));f.owner=new Pc1Timer5(f);check(f.owner.tick()==Integer.parseInt(v[1]),"full native timer return");check(Arrays.equals(f.fields(),ints(v[2])),"native raw fields after full timer");check(Binary.sha256(f.frame.bytes()).equals(v[3]),"whole8004 frame equals original timer stores");check(Binary.sha256(f.callbackBytes()).equals(v[4]),"callback cell stale/clear bytes equal original");check(Binary.sha256(String.join("\n",f.trace).getBytes("UTF-8")).equals(v[5]),"callback ordering and raw boundary states equal actual instructions");if(!f.trace.isEmpty())check(f.blocked,"full timer callback boundary fenced");}
        int[] opts={0,0,0,-1,0,0,0,123,1,9,0,0,0};for(String row:LABELS){String[] v=row.split("\\|",-1);Fixture f=new Fixture(opts);f.code.writeBytes(0,new byte[100000]);f.code.writeBytes(0,bytes(v[0]));byte[] name=bytes(v[1]);for(int n=0;n<name.length;n++)f.bus.writeAddress(Pc1Timer5.CALLBACK+n,name[n]);f.bus.writeAddress(Pc1Timer5.CALLBACK+name.length,0);check(f.scanner.find(Pc1Timer5.CALLBACK)==Integer.parseInt(v[2]),"signed native opcode/label scanner matches actual bytes");}
        Fixture live=new Fixture(opts);int first=live.scanner.find(Pc1Timer5.CALLBACK);live.code.writeU8(first+1,'X');check(live.scanner.find(Pc1Timer5.CALLBACK)==-1&&live.scanner.find(0)==-1,"raw code writes invalidate any prior label result; NULL is native-1");live.bus.writeAddress(Pc1Timer5.CALLBACK+32,0x91);ByteArrayOutputStream wire=new ByteArrayOutputStream();live.callback.save(new DataOutputStream(wire));live.bus.writeAddress(Pc1Timer5.CALLBACK+32,0);live.callback.restore(Pc1Timer5.Memory.loadImage(new DataInputStream(new ByteArrayInputStream(wire.toByteArray()))));check(live.bus.readAddress(Pc1Timer5.CALLBACK+32)==0x91,"verified BSS gap survives independent codec without being cleared as callback bytes");
        production();return checks;
    }
